From c72e85ef172dcc102174ab6a84cf9179e67594af Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:05:01 +0100
Subject: [PATCH] lookandfeel: Draw the round user picture also with software
 rendering

The shader that cuts the user picture round and draws its border doesn't
run with software rendering, so the picture showed as a square over the
frame. Draw the same circle and border with a canvas in that case.

BUG: 408144
---
 lookandfeel/components/UserDelegate.qml | 47 ++++++++++++++++++++++++-
 1 file changed, 46 insertions(+), 1 deletion(-)

diff --git a/lookandfeel/components/UserDelegate.qml b/lookandfeel/components/UserDelegate.qml
index 0f2d8d9c6e..6a569a7924 100644
--- a/lookandfeel/components/UserDelegate.qml
+++ b/lookandfeel/components/UserDelegate.qml
@@ -73,6 +73,8 @@ Item {
             sourceSize: Qt.size(wrapper.faceSize * Screen.devicePixelRatio, wrapper.faceSize * Screen.devicePixelRatio)
             fillMode: Image.PreserveAspectCrop
             anchors.fill: parent
+            // The shader below doesn't run with software rendering, the canvas draws it instead
+            visible: !wrapper.softwareRendering
         }

         Kirigami.Icon {
@@ -94,7 +96,7 @@ Item {

         readonly property Item source: ShaderEffectSource {
             sourceItem: imageSource
-            // software rendering is just a fallback so we can accept not having a rounded avatar here
+            // the canvas below draws the round avatar with software rendering
             hideSource: wrapper.GraphicsInfo.api !== GraphicsInfo.Software
             live: true // otherwise the user in focus will show a blurred avatar
         }
@@ -104,6 +106,49 @@ Item {
         fragmentShader: "qrc:/qt/qml/org/kde/breeze/components/shaders/UserDelegate.frag.qsb"
     }

+    Canvas {
+        anchors.fill: imageSource
+        visible: wrapper.softwareRendering
+
+        readonly property url faceSource: visible ? face.source : ""
+        readonly property real faceAspect: face.implicitHeight > 0 ? face.implicitWidth / face.implicitHeight : 0
+        readonly property color colorBorder: Kirigami.Theme.textColor
+        onFaceSourceChanged: loadFace()
+        Component.onCompleted: loadFace()
+        onImageLoaded: requestPaint()
+        onFaceAspectChanged: requestPaint()
+        onColorBorderChanged: requestPaint()
+
+        function loadFace(): void {
+            if (faceSource.toString() !== "") {
+                loadImage(faceSource);
+            }
+            requestPaint();
+        }
+
+        // Same circle and border as UserDelegate.frag
+        onPaint: {
+            const ctx = getContext("2d");
+            ctx.reset();
+            const center = width / 2;
+            if (face.status === Image.Ready && faceAspect > 0 && isImageLoaded(faceSource)) {
+                const w = Math.max(width, height * faceAspect);
+                const h = Math.max(height, width / faceAspect);
+                ctx.save();
+                ctx.beginPath();
+                ctx.arc(center, center, width * 0.475, 0, 2 * Math.PI);
+                ctx.clip();
+                ctx.drawImage(faceSource, (width - w) / 2, (height - h) / 2, w, h);
+                ctx.restore();
+            }
+            ctx.beginPath();
+            ctx.arc(center, center, width * 0.48, 0, 2 * Math.PI);
+            ctx.lineWidth = width * 0.02;
+            ctx.strokeStyle = colorBorder;
+            ctx.stroke();
+        }
+    }
+
     PlasmaComponents3.Label {
         id: usernameDelegate

